CSS Starter:
.heat { display: grid; grid-template-columns: repeat(var(--cols), var(--cell-size)); gap: var(--cell-gap); }
.heat > i { aspect-ratio: 1; background: var(--heat-2); font-variant-numeric: tabular-nums; }
.heat > i:focus-visible { outline: 2px solid #000000; outline-offset: 1px; }

.kpi { font-size: var(--kpi-size); font-weight: 600; font-variant-numeric: tabular-nums; line-height: 1; }
.kpi-delta { font-size: 0.875rem; color: var(--ink); }
.kpis { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(14rem, 100%), 1fr)); gap: var(--gap); }

.tile { background: var(--panel); color: var(--ink); padding: 12px; font-variant-numeric: tabular-nums; }
.tile.changed { animation: flash 300ms ease-out; }
@keyframes flash { from { background: var(--flash); } to { background: var(--panel); } }

.bar { background: var(--muted); border: 0; min-height: var(--row-h); }
.bar[aria-pressed="true"] { background: var(--selected); outline: 2px solid var(--ink); }
.bar:focus-visible { outline: var(--ring); outline-offset: 2px; }

.compare { display: grid; grid-template-columns: 1fr 1fr var(--delta-w); gap: var(--col-gap); }
.series-a { stroke: var(--series-a); stroke-width: 2.5; }
.series-b { stroke: var(--series-b); stroke-width: 2.5; stroke-dasharray: 6 4; }

.forecast-line { stroke: var(--history); stroke-width: 2.5; stroke-dasharray: var(--dash); fill: none; }
.forecast-band { fill: var(--band); fill-opacity: 0.45; }
.today { stroke: var(--today); stroke-width: 1.5; }

.cohort td { padding: var(--cell-pad); text-align: right; font-variant-numeric: tabular-nums; }
.cohort td[data-v="high"] { background: #99D5CF; color: #0B2E2B; }
.funnel-step { background: var(--vol); height: 32px; }

.ledger td.num { text-align: right; font-variant-numeric: tabular-nums lining-nums; }
.ledger tbody tr:nth-child(even) { background: var(--stripe); }
.neg::before { content: "-"; }

.stage-bar { background: var(--pipeline); height: 28px; width: calc(var(--share) * 100%); }
.target-mark { border-left: 3px solid var(--target); height: 36px; }
.deals td.val { text-align: right; font-variant-numeric: tabular-nums; }

.btn { background: var(--yellow); border: var(--border); box-shadow: var(--shadow); padding: 12px 20px; transition: transform 80ms linear, box-shadow 80ms linear; }
.btn:active { transform: translate(4px, 4px); box-shadow: 2px 2px 0 var(--ink); }
.btn:focus-visible { outline: 3px solid var(--blue); outline-offset: 4px; }

.bento { display: grid; grid-template-columns: repeat(var(--cols), 1fr); grid-auto-rows: minmax(160px, auto); gap: var(--tile-gap); }
.bento > * { background: var(--tile); border-radius: var(--tile-radius); padding: 24px; }
.bento .wide { grid-column: span 2; }

.chrome-btn { background: linear-gradient(#FFFFFF, #C9CED6); border: 1px solid #8A93A0; border-radius: var(--radius); box-shadow: var(--bevel); color: var(--ink); }
.chrome-btn:hover { background: linear-gradient(#FFFFFF, #9EC5F8); }
.chrome-btn:focus-visible { outline: 3px solid var(--pink); outline-offset: 2px; }

.photo { border-radius: var(--blob); overflow: hidden; aspect-ratio: 4 / 5; }
body { background: var(--ground); color: var(--ink); line-height: var(--leading); }
.cta { background: var(--leaf); color: #FFFFFF; border-radius: 999px; padding: 14px 28px; }

.thread { max-width: var(--col); margin-inline: auto; }
.msg { max-width: var(--measure); padding: 12px 16px; border-radius: 12px; }
.msg.new { animation: arrive 150ms ease-out; }
@keyframes arrive { from { opacity: 0; } to { opacity: 1; } }

.shape { width: 120px; height: 120px; background: var(--yellow); transform: rotate(var(--tilt)); border: 3px solid var(--line); }
.dots { background-image: radial-gradient(#1B1B1B 20%, transparent 21%); background-size: var(--dot-size) var(--dot-size); }
.copy { background: var(--paper); padding: 24px; }

.plane { background: var(--plane-mid); box-shadow: var(--shadow-1); position: relative; }
.plane.front { box-shadow: var(--shadow-2); margin-top: -32px; z-index: 2; }
@media (prefers-reduced-motion: reduce) { .plane { transform: none; } }

.kinetic { font-family: "Anybody", sans-serif; font-size: var(--display); font-variation-settings: "wght" var(--wght), "wdth" var(--wdth); transition: font-variation-settings var(--move-ms) ease-in-out; }
.kinetic:hover { --wght: 800; --wdth: 130; }
@media (prefers-reduced-motion: reduce) { .kinetic { transition: none; } }

body { background: var(--paper); color: var(--timber); font-size: 1.0625rem; line-height: 1.6; }
.process { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 32px; align-items: center; }
.price { font-variant-numeric: tabular-nums; color: var(--clay); }

body { font-size: var(--body-size); line-height: 1.6; color: var(--ink); }
.book { background: var(--trust); color: #FFFFFF; min-height: var(--tap); padding: 0 24px; border-radius: 6px; }
.book:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
